def lcf_edges(n, seq, repeats):
    edges=set()
    # cycle
    for i in range(n):
        a=i; b=(i+1)%n
        if a>b: a,b=b,a
        edges.add((a,b))
    full=(seq*repeats)[:n]
    for i,s in enumerate(full):
        j=(i+s)%n
        a,b=sorted((i,j))
        edges.add((a,b))
    return sorted(edges)

def girth(n, edges):
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    import collections
    g=10**9
    for s in range(n):
        dist=[-1]*n; par=[-1]*n
        q=collections.deque([s]); dist[s]=0
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g, dist[u]+dist[v]+1)
    return None if g==10**9 else g
